def polynomial_to_string(n: int, coeffs: list) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        sign = ''
        if coeff < 0:
            sign = '-'
        elif terms:
            sign = '+'

        abs_coeff = abs(coeff)
        coeff_str = ''
        if abs_coeff != 1 or degree == 0:
            coeff_str = str(abs_coeff)

        var_str = ''
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'

        term = sign + coeff_str + var_str
        terms.append(term)

    if not terms:
        return '0'

    return ''.join(terms)
