from typing import List

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # dp[j] will be True if we can achieve volume j using some subset of items
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in volumes:
        # Traverse from V down to vol to avoid using the same item multiple times
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True

    # Find the maximum volume that can be achieved
    max_occupied = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_occupied = j
            break

    return V - max_occupied
```

